import ipaddress
import json
import re

import requests


obs = json.loads(r"""$extract_observables.message""")
CORTEX = "$cortex_url".rstrip("/")
HEADERS = {
    "Authorization": "Bearer $cortex_api_key",
    "Accept": "application/json",
}
WANTED = {
    "VirusTotal": "VirusTotal_GetReport",
    "AbuseIPDB": "AbuseIPDB",
    "MISP": "MISP_",
}

result = {
    "status": "skipped",
    "vt_malicious": 0,
    "verdicts": [],
    "analyzers": [],
    "errors": 0,
    "error_details": [],
}


def add_error(service, message):
    result["errors"] += 1
    result["error_details"].append({
        "service": service,
        "message": message,
    })


def request_json(method, path, timeout=10, **kwargs):
    response = requests.request(
        method,
        f"{CORTEX}{path}",
        headers=HEADERS,
        timeout=timeout,
        **kwargs,
    )
    response.raise_for_status()
    return response.json()


# Ne jamais envoyer une IP privée à VirusTotal ou AbuseIPDB.
ips = []

for value in obs.get("public_ips", []):
    try:
        address = ipaddress.ip_address(value)
    except ValueError:
        add_error("input", f"Adresse IP invalide : {value}")
        continue

    if not address.is_global:
        add_error("input", f"Adresse non publique exclue : {value}")
        continue

    ips.append(str(address))
    break

if not ips:
    result["reason"] = "Aucune IP publique valide à analyser."
    if result["errors"]:
        result["status"] = "error"

else:
    selected = []

    try:
        available = request_json(
            "GET",
            "/api/analyzer/type/ip",
        )

        if not isinstance(available, list):
            raise ValueError("Liste des analyseurs Cortex invalide.")

        # Un analyseur par service pour limiter la durée d'exécution.
        for service, prefix in WANTED.items():
            candidates = [
                analyzer
                for analyzer in available
                if isinstance(analyzer, dict)
                and analyzer.get("name", "").startswith(prefix)
                and analyzer.get("id")
            ]

            if not candidates:
                add_error(
                    service,
                    "Analyseur absent ou non activé pour le type ip.",
                )
                continue

            selected.append((service, candidates[0]))

    except (requests.RequestException, ValueError) as exc:
        add_error("Cortex", str(exc))

    completed = 0

    for service, analyzer in selected:
        ip = ips[0]
        entry = {
            "service": service,
            "analyzer": analyzer["name"],
            "ip": ip,
            "status": "error",
        }
        result["analyzers"].append(entry)

        try:
            job = request_json(
                "POST",
                f"/api/analyzer/{analyzer['id']}/run",
                json={
                    "data": ip,
                    "dataType": "ip",
                    "tlp": 2,
                },
            )

            if not isinstance(job, dict) or not job.get("id"):
                raise ValueError("Réponse de création du job invalide.")

            entry["job_id"] = job["id"]

            report = request_json(
                "GET",
                f"/api/job/{job['id']}/waitreport",
                timeout=25,
                params={"atMost": "20second"},
            )

            if not isinstance(report, dict):
                raise ValueError("Rapport Cortex invalide.")

            entry["status"] = report.get("status", "Unknown")

            if entry["status"] != "Success":
                raise ValueError(
                    f"Job {job['id']} : état {entry['status']}. "
                    "Consultez ce job dans Cortex ; il peut être "
                    "encore en cours ou avoir échoué."
                )

            report_body = report.get("report") or {}
            summary = report_body.get("summary") or {}
            taxonomies = summary.get("taxonomies") or []

            if not isinstance(taxonomies, list):
                raise ValueError("Taxonomies Cortex invalides.")

            entry["summary"] = summary

            for taxonomy in taxonomies:
                level = taxonomy.get("level")
                value = str(taxonomy.get("value", ""))

                result["verdicts"].append({
                    "service": service,
                    "analyzer": analyzer["name"],
                    "ip": ip,
                    "namespace": taxonomy.get("namespace"),
                    "predicate": taxonomy.get("predicate"),
                    "level": level,
                    "value": value,
                })

                if service == "VirusTotal" and level == "malicious":
                    match = re.match(r"(\d+)\s*/", value)
                    count = int(match.group(1)) if match else 1
                    result["vt_malicious"] = max(
                        result["vt_malicious"],
                        count,
                    )

            completed += 1

        except (requests.RequestException, ValueError) as exc:
            entry["error"] = str(exc)
            add_error(service, str(exc))

    if completed and result["errors"] == 0:
        result["status"] = "ok"
    elif completed:
        result["status"] = "partial"
    else:
        result["status"] = "error"

print(json.dumps(result, ensure_ascii=False))

import json

def to_obj(x):
    if isinstance(x, dict):
        return x
    if isinstance(x, str):
        try:
            return json.loads(x)
        except Exception:
            return {}
    return {}

def to_int(value, default=0):
    try:
        n = int(float(value))
        return n if n >= 0 else default
    except Exception:
        return default

def pick(*values):
    for v in values:
        if v not in (None, "", "NULL"):
            return v
    return None

# Entrées
event = to_obj(r"""$normalize_event.message""")
misp = to_obj(r"""$misp_lookup.message""")
cortex = to_obj(r"""$cortex_analyze.message""")
exec_data = to_obj(r"""$exec""")

all_fields = (exec_data.get("all_fields") or {})
exec_rule = (all_fields.get("rule") or {})
exec_agent = (all_fields.get("agent") or {})
exec_data_fields = (all_fields.get("data") or {})

base_alert = event.get("alert") if isinstance(event.get("alert"), dict) else {}
base_rule = (base_alert.get("rule") or {})
base_agent = (base_alert.get("agent") or {})
base_agent_os = (base_agent.get("os") or {})
base_data = (base_alert.get("data") or {})

# Valeurs robustes (plusieurs sources)
rule_id = pick(base_rule.get("id"), event.get("rule_id"), exec_rule.get("id"))
rule_level = to_int(pick(base_rule.get("level"), event.get("rule_level"), exec_rule.get("level")), 0)
rule_fired = to_int(pick(base_rule.get("firedtimes"), event.get("rule_firedtimes"), exec_rule.get("firedtimes")), 1)

timestamp = pick(base_alert.get("timestamp"), event.get("timestamp"), all_fields.get("timestamp"))
agent_name = pick(base_agent.get("name"), event.get("agent_name"), exec_agent.get("name"), "")
agent_os_name = pick(base_agent_os.get("name"), event.get("agent_os_name"), "")
src_ip = pick(base_data.get("srcip"), event.get("src_ip"), exec_data_fields.get("srcip"))

# Alert final pour ML
alert_for_ml = {
    "timestamp": timestamp,
    "rule": {
        "id": rule_id,
        "level": rule_level,
        "firedtimes": rule_fired,
    },
    "agent": {
        "name": agent_name,
        "os": {"name": agent_os_name},
    },
    "data": {
        "srcip": src_ip
    },
}

# Enrichment (ce que ton ML utilise)
enrichment = {
    "misp_hits": to_int(misp.get("misp_hits", 0), 0),
    "vt_malicious": to_int(cortex.get("vt_malicious", 0), 0),
}

partial = (misp.get("status") == "error") or (cortex.get("status") in ("error", "partial"))
enrichment_status = "partial" if partial else "complete"

print(json.dumps({
    "alert": alert_for_ml,
    "enrichment": enrichment,
    "enrichment_status": enrichment_status
}, ensure_ascii=False))

import json

def to_obj(x):
    if isinstance(x, dict):
        return x
    if isinstance(x, str):
        try:
            return json.loads(x)
        except Exception:
            return {}
    return {}

ml_resp = to_obj(r"""$call_ml_api""")
enr = to_obj(r"""$build_ml_enrichment.message""")

status = ml_resp.get("status")
body = ml_resp.get("body")
body_obj = to_obj(body)

ml = body_obj if (status == 200 or str(status) == "200") else {}

# fallback niveau Wazuh depuis enrichment.alert.rule.level
rule_level = 0
try:
    rule_level = int(((enr.get("alert") or {}).get("rule") or {}).get("level") or 0)
except Exception:
    rule_level = 0

try:
    risk = float(ml["risk_score"])
    ml_status = "ok"
except Exception:
    risk = min(rule_level * 6, 100)
    ml_status = "unavailable"

misp_hits = int(enr.get("enrichment", {}).get("misp_hits", 0) or 0)
vt_mal = int(enr.get("enrichment", {}).get("vt_malicious", 0) or 0)

if misp_hits > 0:
    risk = max(risk, 60)
if vt_mal > 0:
    risk = max(risk, 80)
risk = min(risk, 100)

if risk >= 80:
    bucket, severity = "critical", 4
elif risk >= 60:
    bucket, severity = "high", 3
elif risk >= 40:
    bucket, severity = "medium", 2
else:
    bucket, severity = "low", 1

print(json.dumps({
    "risk_score": risk,
    "bucket": bucket,
    "severity": severity,
    "ml_status": ml_status,
    "category": ml.get("category", "unknown"),
    "confidence": ml.get("confidence"),
    "countermeasure": ml.get("countermeasure"),
}))
